      background: #3b82f6;
    }
    button:hover { transform: scale(1.05); }
    button.on  { background: #16a34a; }
    button.off { background: #dc2626; }
  </style>
</head>
<body>
  <h1>Управление реле ESP32</h1>
  <div class="status" id="status">Загрузка...</div>
  <br>
  <button id="btn" onclick="toggleRelay()">Загрузка...</button>

  <script>
    async function updateState() {
      try {
        const res = await fetch('/state');
        const data = await res.json();
        updateUI(data.state);
      } catch (e) {
        document.getElementById('status').textContent = 'Нет связи';
      }
    }

    function updateUI(state) {
      const statusEl = document.getElementById('status');
      const btn = document.getElementById('btn');

      if (state) {
        statusEl.textContent = 'Реле: ВКЛЮЧЕНО';
        statusEl.className = 'status on';
        btn.textContent = 'ВЫКЛЮЧИТЬ';
        btn.className = 'on';
      } else {
        statusEl.textContent = 'Реле: ВЫКЛЮЧЕНО';
        statusEl.className = 'status off';
        btn.textContent = 'ВКЛЮЧИТЬ';
        btn.className = 'off';
      }
    }

    async function toggleRelay() {
      try {
        const res = await fetch('/toggle', { method: 'POST' });
        const data = await res.json();
        updateUI(data.state);
      } catch (e) {
        alert('Ошибка связи с ESP32');
      }
    }

    // Первичная загрузка состояния
    updateState();

    // Опрос состояния каждые 2 секунды (на случай других клиентов)
    setInterval(updateState, 2000);
  </script>
</body>
</html>
)rawliteral";

// ===== Управление реле =====
void setRelay(bool state) {
  relayState = state;
  if (RELAY_ACTIVE_LOW) {
    digitalWrite(RELAY_PIN, state ? LOW : HIGH);
  } else {
    digitalWrite(RELAY_PIN, state ? HIGH : LOW);
  }
  Serial.print("Реле: ");
  Serial.println(state ? "ВКЛ" : "ВЫКЛ");
}

// ===== Обработчики HTTP =====
void handleRoot() {
  server.send_P(200, "text/html", INDEX_HTML);
}

void handleToggle() {
  setRelay(!relayState);
  String json = "{\"state\":" + String(relayState ? "true" : "false") + "}";
  server.send(200, "application/json", json);
}

void handleState() {
  String json = "{\"state\":" + String(relayState ? "true" : "false") + "}";
  server.send(200, "application/json", json);
}

void handleNotFound() {
  server.send(404, "text/plain", "Not Found");
}

// ===== setup =====
void setup() {
  Serial.begin(115200);

  pinMode(RELAY_PIN, OUTPUT);
  setRelay(false);   // при старте — выключено

  // Подключение к WiFi
  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid, password);
  Serial.print("Подключение к WiFi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("IP-адрес ESP32: ");
  Serial.println(WiFi.localIP());

  // Маршруты
  server.on("/", HTTP_GET, handleRoot);
  server.on("/toggle", HTTP_POST, handleToggle);
  server.on("/state", HTTP_GET, handleState);
  server.onNotFound(handleNotFound);

  server.begin();
  Serial.println("Веб-сервер запущен");
}

// ===== loop =====
void loop() {
  server.handleClient();
}
